create table if not exists public.fleet_vehicles (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,unit_code text,vehicle_type text,status text not null default 'active',driver_name text,current_lat double precision,current_lng double precision,odometer_miles numeric,last_service_at timestamptz,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.fleet_drivers (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,email text,phone text,status text not null default 'active',vehicle_id uuid references public.fleet_vehicles(id) on delete set null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.fleet_routes (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,status text not null default 'planned',vehicle_id uuid references public.fleet_vehicles(id) on delete set null,driver_id uuid references public.fleet_drivers(id) on delete set null,route_plan_id uuid references public.route_plans(id) on delete set null,scheduled_for timestamptz,distance_miles numeric,estimated_minutes integer,stops_count integer not null default 0,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.fleet_alerts (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,vehicle_id uuid references public.fleet_vehicles(id) on delete cascade,severity text not null default 'info',alert_type text not null,title text not null,details text,status text not null default 'open',created_at timestamptz not null default now(),resolved_at timestamptz);
create table if not exists public.fleet_metric_snapshots (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,snapshot_date date not null default current_date,vehicles_active integer not null default 0,routes_completed integer not null default 0,stops_completed integer not null default 0,restroom_coverage_score numeric,average_stop_distance_miles numeric,estimated_time_saved_minutes integer not null default 0,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(business_id,snapshot_date));
create index if not exists fleet_vehicles_business_idx on public.fleet_vehicles(business_id);create index if not exists fleet_drivers_business_idx on public.fleet_drivers(business_id);create index if not exists fleet_routes_business_idx on public.fleet_routes(business_id);create index if not exists fleet_alerts_business_status_idx on public.fleet_alerts(business_id,status);create index if not exists fleet_metrics_business_date_idx on public.fleet_metric_snapshots(business_id,snapshot_date desc);
alter table public.fleet_vehicles enable row level security;alter table public.fleet_drivers enable row level security;alter table public.fleet_routes enable row level security;alter table public.fleet_alerts enable row level security;alter table public.fleet_metric_snapshots enable row level security;
create or replace function public.has_fleet_access(p_business_id uuid) returns boolean language sql stable security invoker as $$ select exists(select 1 from public.business_members bm join public.businesses b on b.id=bm.business_id where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role in ('owner','admin','manager') and b.business_tier='fleet'::public.business_tier) $$;
create policy fleet_vehicles_select on public.fleet_vehicles for select to authenticated using (public.has_fleet_access(business_id));create policy fleet_vehicles_write on public.fleet_vehicles for all to authenticated using (public.has_fleet_access(business_id)) with check (public.has_fleet_access(business_id));
create policy fleet_drivers_select on public.fleet_drivers for select to authenticated using (public.has_fleet_access(business_id));create policy fleet_drivers_write on public.fleet_drivers for all to authenticated using (public.has_fleet_access(business_id)) with check (public.has_fleet_access(business_id));
create policy fleet_routes_select on public.fleet_routes for select to authenticated using (public.has_fleet_access(business_id));create policy fleet_routes_write on public.fleet_routes for all to authenticated using (public.has_fleet_access(business_id)) with check (public.has_fleet_access(business_id));
create policy fleet_alerts_select on public.fleet_alerts for select to authenticated using (public.has_fleet_access(business_id));create policy fleet_alerts_write on public.fleet_alerts for all to authenticated using (public.has_fleet_access(business_id)) with check (public.has_fleet_access(business_id));
create policy fleet_metrics_select on public.fleet_metric_snapshots for select to authenticated using (public.has_fleet_access(business_id));
create or replace function public.fleet_dashboard_summary(p_business_id uuid) returns jsonb language plpgsql security invoker as $$ declare result jsonb; begin if not public.has_fleet_access(p_business_id) then raise exception 'fleet entitlement required'; end if; select jsonb_build_object('vehicles',(select count(*) from public.fleet_vehicles where business_id=p_business_id and status='active'),'drivers',(select count(*) from public.fleet_drivers where business_id=p_business_id and status='active'),'routes_active',(select count(*) from public.fleet_routes where business_id=p_business_id and status in ('planned','active')),'routes_completed',(select count(*) from public.fleet_routes where business_id=p_business_id and status='completed'),'open_alerts',(select count(*) from public.fleet_alerts where business_id=p_business_id and status='open'),'stops',coalesce((select sum(stops_count) from public.fleet_routes where business_id=p_business_id and status='completed'),0),'time_saved_minutes',coalesce((select sum(estimated_time_saved_minutes) from public.fleet_metric_snapshots where business_id=p_business_id),0)) into result; return result; end $$;
revoke all on function public.fleet_dashboard_summary(uuid) from public,anon;grant execute on function public.fleet_dashboard_summary(uuid) to authenticated;
